import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Event Handling', () => {
  test('Has an input with id "item-input"', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
if (!input) throw new Error('No input with id "item-input" found');
if (input.tagName !== 'INPUT') throw new Error('Element should be an <input>');
  });

  test('Typing and clicking Add adds item to list', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
const btn = root.querySelector('#add-btn');
if (!btn) throw new Error('No button with id "add-btn" found');
const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nativeInputValueSetter.call(input, 'Test Item');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
const list = root.querySelector('#item-list');
if (!list) throw new Error('No <ul> with id "item-list" found');
const items = list.querySelectorAll('li');
if (items.length < 1) throw new Error('Expected at least 1 item in the list');
if (!items[items.length - 1].textContent.includes('Test Item'))
  throw new Error('Last item should contain "Test Item"');
  });

  test('Input clears after adding an item', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
if (input.value !== '') throw new Error('Input should be empty after adding an item');
  });

  test('Can add multiple items', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#item-input');
const btn = root.querySelector('#add-btn');
const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nativeInputValueSetter.call(input, 'Item A');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
nativeInputValueSetter.call(input, 'Item B');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
btn.click();
await tick();
const items = root.querySelectorAll('#item-list li');
if (items.length < 2) throw new Error('Expected at least 2 items in the list');
  });
});
